<?php
namespace Tests\Feature;
use App\Models\{Benefit,JpHold,Membership,Partner,RewardTransaction,Redemption,Unlock,UnlockParticipation,User}; use App\Services\UnlockParticipationService; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Str; use Tests\TestCase;
class UnlockTrustedFulfillmentTest extends TestCase { use RefreshDatabase;
 public function test_trusted_fulfillment_releases_hold_and_awards_configured_bonus_once():void{$u=User::factory()->create();$p=$this->participation($u,['jp_deposit'=>7,'jp_completion_bonus'=>11]);JpHold::create(['user_id'=>$u->id,'unlock_participation_id'=>$p->id,'amount'=>7,'status'=>JpHold::HELD,'held_at'=>now()]);$s=app(UnlockParticipationService::class);$s->fulfill($p,$u,'admin_manual','verified',null,true);$s->fulfill($p,$u,'admin_manual','verified',null,true);$this->assertSame(UnlockParticipation::FULFILLED,$p->fresh()->status);$this->assertSame(JpHold::RELEASED,JpHold::sole()->status);$this->assertDatabaseCount('reward_transactions',1);$this->assertDatabaseHas('reward_transactions',['unlock_participation_id'=>$p->id,'amount'=>11,'reward_type'=>'JP','source'=>'unlock_fulfillment']);}
 public function test_zero_deposit_free_user_receives_bonus_and_zero_bonus_creates_none():void{$u=User::factory()->create();$s=app(UnlockParticipationService::class);$p=$this->participation($u,['jp_deposit'=>0,'jp_completion_bonus'=>10]);$s->fulfill($p,$u,'admin_manual','verified',null,true);$this->assertDatabaseMissing('jp_holds',['unlock_participation_id'=>$p->id]);$this->assertDatabaseHas('reward_transactions',['unlock_participation_id'=>$p->id,'amount'=>10]);$q=$this->participation(User::factory()->create(),['jp_completion_bonus'=>0]);$s->fulfill($q,$u,'admin_manual','verified',null,true);$this->assertDatabaseCount('reward_transactions',1);}
 public function test_redemption_signal_uses_same_idempotent_financial_outcome():void{$u=User::factory()->create();$partner=Partner::create(['name'=>'P'.uniqid(),'slug'=>'p'.uniqid(),'entity_type'=>'BUSINESS','partner_type'=>'OTHER','status'=>'published']);$b=Benefit::create(['partner_id'=>$partner->id,'slug'=>'b'.uniqid(),'title'=>'B','status'=>'published']);$p=$this->participation($u,['jp_deposit'=>3,'jp_completion_bonus'=>4,'linked_benefit_id'=>$b->id]);JpHold::create(['user_id'=>$u->id,'unlock_participation_id'=>$p->id,'amount'=>3,'status'=>JpHold::HELD,'held_at'=>now()]);$m=Membership::create(['user_id'=>$u->id,'status'=>'active','starts_at'=>now(),'ends_at'=>now()->addDay(),'amount_paid'=>0]);$r=Redemption::create(['public_id'=>(string)Str::ulid(),'code'=>'ABC123','user_id'=>$u->id,'membership_id'=>$m->id,'partner_id'=>$partner->id,'benefit_id'=>$b->id,'partner_name'=>$partner->name,'location_name'=>'N/A','benefit_title'=>$b->title,'status'=>'confirmed','expires_at'=>now()->addMinute(),'confirmed_at'=>now()]);$s=app(UnlockParticipationService::class);$s->fulfillForRedemption($r->id,$u->id,$b->id);$s->fulfillForRedemption($r->id,$u->id,$b->id);$this->assertSame(UnlockParticipation::FULFILLED,$p->fresh()->status);$this->assertSame(JpHold::RELEASED,JpHold::sole()->status);$this->assertDatabaseCount('reward_transactions',1);}
 public function test_partner_owner_and_manager_may_fulfill_only_their_own_unlock():void{$partner=Partner::create(['name'=>'P'.uniqid(),'slug'=>'p'.uniqid(),'entity_type'=>'BUSINESS','partner_type'=>'OTHER','status'=>'published']);$owner=User::factory()->create();$manager=User::factory()->create();$partner->users()->attach([$owner->id=>['role'=>'owner'],$manager->id=>['role'=>'manager']]);foreach([$owner,$manager] as $actor){$p=$this->participation(User::factory()->create(),['partner_id'=>$partner->id,'jp_completion_bonus'=>1]);$this->actingAs($actor)->post("/partner/{$partner->slug}/desbloqueos/{$p->unlock->slug}/participaciones/{$p->id}/cumplir",['note'=>'checked'])->assertSessionHasNoErrors();$this->assertSame(UnlockParticipation::FULFILLED,$p->fresh()->status);} $other=Partner::create(['name'=>'O'.uniqid(),'slug'=>'o'.uniqid(),'entity_type'=>'BUSINESS','partner_type'=>'OTHER','status'=>'published']);$bad=User::factory()->create();$other->users()->attach($bad->id,['role'=>'owner']);$p=$this->participation(User::factory()->create(),['partner_id'=>$partner->id]);$this->actingAs($bad)->post("/partner/{$partner->slug}/desbloqueos/{$p->unlock->slug}/participaciones/{$p->id}/cumplir")->assertForbidden();$this->actingAs(User::factory()->create())->post("/partner/{$partner->slug}/desbloqueos/{$p->unlock->slug}/participaciones/{$p->id}/cumplir")->assertForbidden();}
 private function participation(User $u,array $o=[]):UnlockParticipation{$x=Unlock::create(array_merge(['title'=>'U'.uniqid(),'slug'=>'u'.uniqid(),'origin'=>'JAKAWI','type'=>'EXPERIENCE','minimum_commitments'=>1,'free_user_eligible'=>true,'member_eligible'=>true,'jp_deposit'=>0,'jp_completion_bonus'=>0,'status'=>Unlock::UNLOCKED],$o));return UnlockParticipation::create(['unlock_id'=>$x->id,'user_id'=>$u->id,'status'=>UnlockParticipation::CONFIRMED,'confirmed_at'=>now()]);}}
